begin;
insert into auth.users(id,is_anonymous) values('10000000-0000-4000-8000-000000000001',false),('10000000-0000-4000-8000-000000000002',false),('10000000-0000-4000-8000-000000000003',false),('10000000-0000-4000-8000-000000000004',true);
insert into launcher_private.admins(user_id) values('10000000-0000-4000-8000-000000000001');
insert into public.launcher_games(id,engine_key,title,status,access_model) values('gift-one','gift-one','One','published','premium'),('gift-two','gift-two','Two','published','premium'),('gift-three','gift-three','Three','published','premium'),('gift-four','gift-four','Four','published','premium');
create function public.gift_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select public.launcher_admin_set_starter(array['gift-one','gift-two','gift-three'],true,'QA configure gift');
do $$begin
 begin perform public.launcher_admin_set_starter(array['gift-one','gift-two'],true,'QA invalid');raise exception 'FAIL fewer than three';exception when invalid_parameter_value then null;end;
 begin perform public.launcher_admin_set_starter(array['gift-one','gift-one','gift-three'],true,'QA duplicates');raise exception 'FAIL duplicate games';exception when invalid_parameter_value then null;end;
 begin perform public.launcher_admin_set_starter(array['gift-one','gift-two','unknown'],true,'QA invalid game');raise exception 'FAIL unknown game';exception when invalid_parameter_value then null;end;
end$$;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select public.gift_assert(jsonb_array_length(public.launcher_my_access(auth.uid())->'starterGames')=0,'off mode grants nothing');
do $$begin
 begin perform public.launcher_admin_set_starter(array['gift-one','gift-two','gift-four'],true,'QA user change');raise exception 'FAIL user configured starter';exception when insufficient_privilege then null;end;
 begin perform public.launcher_my_access('10000000-0000-4000-8000-000000000003');raise exception 'FAIL read another user';exception when insufficient_privilege then null;end;
 begin perform public.launcher_my_access(null);raise exception 'FAIL missing expected owner';exception when insufficient_privilege then null;end;
end$$;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select public.launcher_admin_command('mode','{"mode":"pilot"}','QA gift pilot');
select public.launcher_admin_command('pilot','{"user_id":"10000000-0000-4000-8000-000000000002","enabled":true}','QA existing user');
select public.launcher_admin_command('pilot','{"user_id":"10000000-0000-4000-8000-000000000003","enabled":true}','QA new user');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select public.gift_assert(jsonb_array_length(public.launcher_my_access(auth.uid())->'starterGames')=3,'existing account gets three gifts on first visit');
select public.gift_assert(jsonb_array_length(public.launcher_my_access(auth.uid())->'entitlements')=3,'repeat claim never duplicates');
select public.gift_assert((public.launcher_check_access_v2('gift-two')->>'allowed')::boolean,'gift unlocks premium game');
select public.gift_assert(not (public.launcher_check_access_v2('gift-four')->>'allowed')::boolean,'gift does not unlock whole catalog');
select public.gift_assert((select count(*)=3 and bool_and(expires_at is null and source='starter' and order_id is null) from public.launcher_entitlements),'permanent gift is not a paid order');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select public.launcher_admin_set_starter(array['gift-one','gift-two','gift-four'],true,'QA next gift set');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select public.gift_assert(public.launcher_my_access(auth.uid())->'starterGames' ? 'gift-three','existing gift retained after config change');
select public.gift_assert(not (public.launcher_my_access(auth.uid())->'starterGames' ? 'gift-four'),'old account cannot claim new set');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select public.gift_assert(public.launcher_my_access(auth.uid())->'starterGames' ? 'gift-four','new claimant gets new set');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
do $$begin begin perform public.launcher_my_access(auth.uid());raise exception 'FAIL guest gift';exception when insufficient_privilege then null;end;end$$;
reset role;
select public.gift_assert((select count(*)=2 from launcher_private.starter_claims),'only registered pilot accounts claimed');
select public.gift_assert((select count(*)=6 from public.launcher_entitlements),'exactly six gifts for two accounts');
rollback;
